/app/2963950/","popularity":0,"critic_score":null,"screenshots":[{"url":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2963950/553029204f0bef1ba1bfd1542091b299fd8b9075/ss_553029204f0bef1ba1bfd1542091b299fd8b9075.1920x1080.jpg?t=1788989521","title":"Официальный скриншот 1"},{"url":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2963950/ec30bb3d1c237eaf9676d37f06193aea2dfd6aa2/ss_ec30bb3d1c237eaf9676d37f06193aea2dfd6aa2.1920x1080.jpg?t=1788989521","title":"Официальный скриншот 2"},{"url":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2963950/1b25c89e192c3c1ae7636543adea5229e2938553/ss_1b25c89e192c3c1ae7636543adea5229e2938553.1920x1080.jpg?t=1788989521","title":"Официальный скриншот 3"},{"url":"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/2963950/7273be1b6a0a1e762f56983a676e4235fc7bad49/ss_7273be1b6a0a1e762f56983a676e4235fc7bad49.1920x1080.jpg?t=1788989521","title":"Официальный скриншот 4"}],"trailers":[],"guides":[{"title":"Перед релизом: Persona 4 Revival","category":"Подготовка","content":"Новое переосмысление Persona 4: расследование тайн Инабы, дружба и пошаговые сражения. Игра ещё не вышла.\n\nИгра ещё не вышла. Проверенных прохождений и модов пока нет. Перед покупкой уточните дату выхода и платформы на официальной странице.","url":"https://store.steampowered.com/app/2963950/","source":"Официальная страница Steam"}]}]$catalog$::jsonb) loop
insert into public.users(name,email,password) values(item->>'developer',md5(item->>'developer')||'@gamekritik.invalid','!not-a-login!') on conflict do nothing;
insert into public.games(steam_app_id,title,description,release_date,developer,platform,cover_image,hero_image,genre,publisher,release_status,release_label,first_release_year,source_url,popularity,critic_score)
values((item->>'steam_app_id')::integer,item->>'title',item->>'description',(item->>'release_date')::date,item->>'developer',item->>'platform',item->>'cover_image',item->>'hero_image',item->>'genre',item->>'publisher',item->>'release_status',item->>'release_label',(item->>'first_release_year')::integer,item->>'source_url',(item->>'popularity')::integer,(item->>'critic_score')::integer)
on conflict(steam_app_id) do update set title=excluded.title,description=excluded.description,release_date=excluded.release_date,cover_image=excluded.cover_image,hero_image=excluded.hero_image,genre=excluded.genre,publisher=excluded.publisher,release_status=excluded.release_status,release_label=excluded.release_label,first_release_year=excluded.first_release_year,source_url=excluded.source_url,popularity=excluded.popularity,critic_score=excluded.critic_score returning game_id into gid;
for media in select value from jsonb_array_elements(item->'screenshots') loop
insert into public.screenshots(game_id,image_url,description) select gid,media->>'url',media->>'title' where not exists(select 1 from public.screenshots where game_id=gid and image_url=media->>'url'); end loop;
for media in select value from jsonb_array_elements(item->'trailers') loop
insert into public.trailers(game_id,title,video_url,thumbnail_url,source_url) select gid,media->>'title',media->>'url',media->>'thumbnail',media->>'source' where not exists(select 1 from public.trailers where game_id=gid and video_url=media->>'url'); end loop;
for media in select value from jsonb_array_elements(item->'guides') loop
insert into public.guides(user_id,game_id,title,content,category,author,source_url,cover_image,source_name) select (select user_id from public.users where email='editorial@gamekritik.invalid'),gid,media->>'title',media->>'content',media->>'category','GameKritik · подборка',media->>'url',item->>'cover_image',media->>'source' where not exists(select 1 from public.guides where game_id=gid and source_url=media->>'url'); end loop;
end loop; end $import$;
commit;
select count(*) games from public.games;
